<script setup lang="ts">
import {Link,useForm} from '@inertiajs/vue3';import {computed} from 'vue';import type {PdfTemplate} from '@/types';
type TemplateForm={name:string;document_type:string;page_size:'A4'|'LETTER'|'LEGAL';qr_page:number;qr_x:number;qr_y:number;qr_width:number;qr_height:number;coordinates:Record<string,string>;is_active:boolean};const props=defineProps<{template?:PdfTemplate}>();const form=useForm<TemplateForm>({name:props.template?.name??'',document_type:props.template?.document_type??'',page_size:props.template?.page_size??'A4',qr_page:props.template?.qr_page??1,qr_x:props.template?.qr_x??150,qr_y:props.template?.qr_y??230,qr_width:props.template?.qr_width??35,qr_height:props.template?.qr_height??35,coordinates:(props.template?.coordinates??{}) as Record<string,string>,is_active:props.template?.is_active??true});
const dimensions=computed(()=>form.page_size==='LETTER'?{w:216,h:279}:form.page_size==='LEGAL'?{w:216,h:356}:{w:210,h:297});const qrStyle=computed(()=>({left:`${Math.min(100,form.qr_x/dimensions.value.w*100)}%`,top:`${Math.min(100,form.qr_y/dimensions.value.h*100)}%`,width:`${Math.min(100,form.qr_width/dimensions.value.w*100)}%`,height:`${Math.min(100,form.qr_height/dimensions.value.h*100)}%`}));const submit=()=>props.template?form.put(route('admin.templates.update',props.template.id)):form.post(route('admin.templates.store'));
const types={MEDICAL_CERTIFICATE:'Certificado médico',MEDICAL_REPORT:'Informe médico',PRESCRIPTION:'Receta médica',LAB_RESULT:'Resultado de laboratorio',REFERRAL:'Referencia médica',OTHER:'Otro'};
</script>
<template><form class="template-form" @submit.prevent="submit"><div class="panel form-panel"><div class="form-grid"><div class="field"><label for="name">Nombre</label><input id="name" v-model="form.name" required maxlength="255"><span class="field-error">{{ form.errors.name }}</span></div><div class="field"><label for="document-type">Tipo de documento</label><select id="document-type" v-model="form.document_type"><option value="">Cualquier tipo</option><option v-for="(label,value) in types" :key="value" :value="value">{{ label }}</option></select><span class="field-error">{{ form.errors.document_type }}</span></div><div class="field"><label for="page-size">Tamaño de página</label><select id="page-size" v-model="form.page_size"><option value="A4">A4</option><option value="LETTER">Carta</option><option value="LEGAL">Legal</option></select><span class="field-error">{{ form.errors.page_size }}</span></div><div class="field"><label for="qr-page">Página del QR</label><input id="qr-page" v-model.number="form.qr_page" type="number" min="1" max="999" required><span class="field-error">{{ form.errors.qr_page }}</span></div><div class="field"><label for="qr-x">Posición X (mm)</label><input id="qr-x" v-model.number="form.qr_x" type="number" min="0" max="1000" step="0.1" required><span class="field-error">{{ form.errors.qr_x }}</span></div><div class="field"><label for="qr-y">Posición Y (mm)</label><input id="qr-y" v-model.number="form.qr_y" type="number" min="0" max="1000" step="0.1" required><span class="field-error">{{ form.errors.qr_y }}</span></div><div class="field"><label for="qr-width">Ancho (mm)</label><input id="qr-width" v-model.number="form.qr_width" type="number" min="0.1" max="500" step="0.1" required><span class="field-error">{{ form.errors.qr_width }}</span></div><div class="field"><label for="qr-height">Alto (mm)</label><input id="qr-height" v-model.number="form.qr_height" type="number" min="0.1" max="500" step="0.1" required><span class="field-error">{{ form.errors.qr_height }}</span></div></div><label class="check-row"><input v-model="form.is_active" type="checkbox"> Plantilla activa</label><div class="form-actions"><Link class="button button--outline-small" :href="route('admin.templates.index')">Cancelar</Link><button class="button button--admin" :disabled="form.processing">{{ form.processing?'Guardando...':'Guardar plantilla' }}</button></div></div><aside class="panel calibration"><p class="kicker">Vista de calibración</p><h2>Página {{ form.qr_page }}</h2><p>La escala representa milímetros sobre {{ form.page_size }}. El cuadro marca el área exacta reservada al QR.</p><div class="paper-preview calibrated-paper" :style="{aspectRatio:`${dimensions.w}/${dimensions.h}`}"><div class="paper-head"><span></span><b></b></div><div class="qr-target" :style="qrStyle"><strong>QR</strong></div></div><dl class="coordinate-summary"><div><dt>X / Y</dt><dd>{{ form.qr_x }} / {{ form.qr_y }} mm</dd></div><div><dt>Ancho / alto</dt><dd>{{ form.qr_width }} / {{ form.qr_height }} mm</dd></div></dl></aside></form></template>
